face.layout_source:
// spectral-freeze.face: the panel for tap/examples/spectral/spectral-freeze.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/spectral/spectral-freeze.face --meta <graph>.cragmeta

face "Spectral Freeze" {
  row(gap = 10) {
    box "Freeze" { toggle "Freeze" (freeze) }
    box "Mix" { vslider "Wet" (wet_level) vslider "Dry" (dry_level) }
    viz(grow = 1)
  }
}
